document.addEventListener("DOMContentLoaded", () => {
  const year = new Date().getFullYear();
  const footer = document.querySelector(".site-footer");
  if (footer) {
    const yearLabel = document.createElement("span");
    yearLabel.textContent = String(year);
    footer.appendChild(yearLabel);
  }

  const languageSelect = document.getElementById("language-select");
  if (!languageSelect) return;

  const originalTextNodes = new WeakMap();
  let activeLanguage = "en";
  const translateDynamicText = (root = document) => {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    let node;
    while ((node = walker.nextNode())) {
      if (!originalTextNodes.has(node)) originalTextNodes.set(node, node.nodeValue);
      const original = originalTextNodes.get(node);
      const trimmed = original.trim();
      const translated = (dynamicPhraseMap[activeLanguage] || {})[trimmed];
      if (translated) node.nodeValue = original.replace(trimmed, translated);
      else if (node.nodeValue !== original && Object.values(dynamicPhraseMap).some(map => Object.values(map).includes(node.nodeValue.trim()))) {
        node.nodeValue = original;
      }
    }
    root.querySelectorAll?.("[data-i18n-placeholder], [data-i18n-aria]").forEach(element => {
      const placeholderKey = element.dataset.i18nPlaceholder;
      const ariaKey = element.dataset.i18nAria;
      if (placeholderKey && translations[activeLanguage][placeholderKey]) element.setAttribute("placeholder", translations[activeLanguage][placeholderKey]);
      if (ariaKey && translations[activeLanguage][ariaKey]) element.setAttribute("aria-label", translations[activeLanguage][ariaKey]);
    });
  };

  const applyLanguage = (language) => {
    const selected = translations[language] ? language : "en";
    activeLanguage = selected;
    window.smartRouteLanguage = selected;
    document.dispatchEvent(new Event("smartroute:languagechange"));
    document.documentElement.lang = selected;
    document.documentElement.dir = selected === "ur" ? "rtl" : "ltr";
    document.querySelectorAll("[data-i18n]").forEach((element) => {
      const key = element.dataset.i18n;
      if (translations[selected][key]) element.textContent = translations[selected][key];
    });
    translateDynamicText(document);
    languageSelect.value = selected;
    try { localStorage.setItem("smartrouteLanguage", selected); } catch (error) {}
  };

  let savedLanguage = "en";
  try { savedLanguage = localStorage.getItem("smartrouteLanguage") || "en"; } catch (error) {}
  languageSelect.addEventListener("change", () => applyLanguage(languageSelect.value));
  applyLanguage(savedLanguage);
  const languageObserver = new MutationObserver(records => {
    for (const record of records) {
      record.addedNodes.forEach(node => {
        if (node.nodeType === Node.TEXT_NODE) translateDynamicText(node.parentNode || document);
        else if (node.nodeType === Node.ELEMENT_NODE) translateDynamicText(node);
      });
    }
  });
  languageObserver.observe(document.body, { childList: true, subtree: true });
});
